using System;
using System.Collections;
using System.Collections.Generic;
using System.Linq;
using System.Reflection;
using UnityEngine;
// Native organizations retain ownership/membership and save data. Rankings are derived caches.
public static class NativeOrganizations {
 const BindingFlags Flags=BindingFlags.Instance|BindingFlags.Public|BindingFlags.NonPublic;
 public static readonly string[] Kinds={"City","Kingdom","Family","Clan","Alliance","Culture","Religion","Language","Subspecies"};
 static readonly string[] Managers={"cities","kingdoms","families","clans","alliances","cultures","religions","languages","subspecies"};
 public sealed class Standing {public object organization;public int kind,population;public double wealth,talent,military,development,stability,score;public int rank;}
 static Dictionary<object,Standing> standings=new Dictionary<object,Standing>();
 static object map;static IEnumerator pass;static List<Standing> pending;static float next;static int revision;
 public static object Member(object o,string name){if(o==null)return null;for(Type t=o.GetType();t!=null;t=t.BaseType){var p=t.GetProperty(name,Flags|BindingFlags.DeclaredOnly);if(p!=null)return p.GetValue(o,null);var f=t.GetField(name,Flags|BindingFlags.DeclaredOnly);if(f!=null)return f.GetValue(o);}return null;}
 public static object Invoke(object o,string name,params object[] args){if(o==null)return null;var m=o.GetType().GetMethods(Flags).FirstOrDefault(x=>x.Name==name&&x.GetParameters().Length==args.Length&&x.GetParameters().Select((p,i)=>args[i]==null?!p.ParameterType.IsValueType:p.ParameterType.IsInstanceOfType(args[i])).All(b=>b));if(m==null)throw new MissingMethodException(o.GetType().Name,name);return m.Invoke(o,args);}
 public static BaseSystemData Data(object o){return Member(o,"data") as BaseSystemData;}
 public static IEnumerable Objects(int kind){var w=World.world;var manager=Member(w,Managers[kind]);return Member(manager,"list") as IEnumerable??manager as IEnumerable??new object[0];}
 public static IEnumerable Units(object o){var m=o==null?null:o.GetType().GetMethod("getUnits",Flags,null,Type.EmptyTypes,null);return (m==null?Member(o,"units"):m.Invoke(o,null)) as IEnumerable??new object[0];}
 public static string Name(object o){var d=Data(o);return d==null?"—":d.name+" #"+d.id;}
 static bool Alive(object o){if(o==null)return false;var m=o.GetType().GetMethod("isAlive",Flags,null,Type.EmptyTypes,null);if(m==null)return true;var result=m.Invoke(o,null);return !(result is bool)||(bool)result;}
 public static double Score(int population,double wealth,double talent,double military,double development,double stability){if(population<=0)return 0;return Math.Sqrt(population)*12+Math.Log(1+Math.Max(0,wealth))*8+Math.Max(0,talent)/Math.Sqrt(population)*2+Math.Sqrt(Math.Max(0,military))*5+Math.Sqrt(Math.Max(0,development))*4+Math.Max(0,Math.Min(100,stability))*.2;}
 static IEnumerator Scan(){pending=new List<Standing>();for(int kind=0;kind<Kinds.Length;kind++)foreach(var o in Objects(kind)){if(!Alive(o))continue;var s=new Standing{organization=o,kind=kind};foreach(var item in Units(o)){yield return null;var a=item as Actor;if(a==null||!a.isAlive())continue;s.population++;var d=(ActorData)a.getData();s.wealth+=Math.Max(0,d.money);s.talent+=NativeProgression.Ability(a,0)+NativeProgression.Ability(a,1)+NativeProgression.Ability(a,2)+NativeProgression.Ability(a,3);if(a.is_profession_warrior)s.military+=1+NativeProgression.Ability(a,4);}
  var c=o as City;if(c!=null){var e=GodWorldRuntime.State(c);s.wealth+=GodWorldRuntime.GetGold(c)+e.business.gold+e.households.gold+e.education.gold+e.military.gold+e.politics.gold;s.development=e.infrastructure+e.machinery+e.knowledge+e.steamPlant*10+e.factory*20+e.powerPlant*30+e.laboratory*40;s.stability=(e.satisfaction+e.loyalty)/2;}
  var k=o as Kingdom;if(k!=null)s.wealth+=NativeLifecycle.NationalBalance(k,false);
  // For supra-city organizations count each city's infrastructure once, not once per member.
  var getCities=o.GetType().GetMethod("getCities",Flags,null,Type.EmptyTypes,null);if(c==null&&getCities!=null){var cities=getCities.Invoke(o,null) as IEnumerable;var seen=new HashSet<City>();if(cities!=null)foreach(var item in cities){yield return null;var city=item as City;if(city==null||!seen.Add(city))continue;var e=GodWorldRuntime.State(city);s.development+=e.infrastructure+e.machinery+e.knowledge;s.wealth+=GodWorldRuntime.GetGold(city);}}
  s.score=Score(s.population,s.wealth,s.talent,s.military,s.development,s.stability);if(s.population>0)pending.Add(s);yield return null;}
  var completed=new Dictionary<object,Standing>();foreach(var group in pending.GroupBy(s=>s.kind)){var sorted=group.OrderByDescending(s=>s.score).ThenBy(s=>Data(s.organization)==null?0:Data(s.organization).id).ToList();int rank=0;double previous=Double.NaN;for(int i=0;i<sorted.Count;i++){var s=sorted[i];if(i==0||Math.Abs(previous-s.score)>1e-6)rank=i+1;s.rank=rank;previous=s.score;completed[s.organization]=s;}}standings=completed;revision++;pending=null;}
 public static void Tick(){try{object current=Member(World.world,"map_stats");if(!System.Object.ReferenceEquals(current,map)){map=current;standings.Clear();pass=null;pending=null;next=0;}if(World.world==null)return;if(pass==null){if(Time.unscaledTime<next)return;pass=Scan();}for(int i=0;i<128;i++)if(!pass.MoveNext()){pass=null;next=Time.unscaledTime+30;break;}}catch(Exception e){pass=null;pending=null;next=Time.unscaledTime+5;Debug.LogWarning("GodWorld organization scan: "+e.Message);}}
 public static Standing Get(object o){Standing s;return o!=null&&standings.TryGetValue(o,out s)?s:null;}
 public static string Effect(string kind){switch(kind){case "City":case "Culture":return "建设、制造品质、工业产能与科研";case "Kingdom":return "忠诚、征兵速度与装备耐久";case "Family":return "贸易与领袖治理";case "Clan":case "Religion":return "领袖治理、征兵速度与装备耐久";case "Alliance":return "贸易、征兵速度与装备耐久";case "Language":return "贸易与科研";case "Subspecies":return "建设、制造品质与装备耐久";default:return "—";}}
 public static int Mode(object o){int n;var d=Data(o);if(d==null)return 0;d.get("godworld.organization.mode",out n,0);return n;}
 public static int Manual(object o){int n;var d=Data(o);if(d==null)return 0;d.get("godworld.organization.bonus",out n,15);return Math.Max(0,Math.Min(25,n));}
 public static void Configure(object o,int mode,int bonus){var d=Data(o);if(d==null)throw new Exception("组织数据不可用");d.set("godworld.organization.mode",Math.Max(0,Math.Min(2,mode)));d.set("godworld.organization.bonus",Math.Max(0,Math.Min(25,bonus)));}
 public static double Strength(object o){if(o==null||!Alive(o))return 0;int mode=Mode(o);if(mode==1)return 0;var s=Get(o);if(mode==2)return Manual(o)/100.0;return s!=null&&s.rank==1?.15:0;}
 static bool Applies(string type,string role){switch(type){case "City":return role=="production"||role=="research";case "Kingdom":return role=="governance"||role=="combat";case "Family":return role=="commerce"||role=="governance";case "Clan":return role=="combat"||role=="governance";case "Alliance":return role=="commerce"||role=="combat";case "Culture":return role=="production"||role=="research";case "Religion":return role=="governance"||role=="combat";case "Language":return role=="commerce"||role=="research";case "Subspecies":return role=="production"||role=="combat";default:return false;}}
 static object AllianceOf(Kingdom k){return k==null?null:k.getAlliance();}
 public static double Bonus(Actor a,string role){if(a==null)return 0;var c=a.getCity();var k=GodWorldRuntime.Nation(c);object[] groups={c,k,a.family,a.clan,AllianceOf(k),a.culture,a.religion,a.language,a.subspecies};double sum=0;for(int i=0;i<groups.Length;i++)if(Applies(Kinds[i],role))sum+=Strength(groups[i]);return Math.Min(.30,sum);}
 public static double CityBonus(City c,string role){if(c==null)return 0;double sum=Applies("City",role)?Strength(c):0;var k=GodWorldRuntime.Nation(c);if(Applies("Kingdom",role))sum+=Strength(k);if(Applies("Alliance",role))sum+=Strength(AllianceOf(k));var leader=c.leader;if(leader!=null)sum=Math.Max(sum,Bonus(leader,role));return Math.Min(.30,sum);}
 public static int Scale(int n,double bonus){return n<=0?n:(int)Math.Min(Int32.MaxValue,Math.Floor(n*(1+Math.Max(0,Math.Min(.30,bonus)))));}
 public static int ResearchWork(Actor a,int n){return Scale(n,Bonus(a,"research"));}
 public static int Governance(City c,int original){return (int)Math.Min(Int32.MaxValue,(long)original+(int)Math.Round(CityBonus(c,"governance")*30));}
 public static int Durability(Actor a,int damage){return damage<=0?damage:Math.Max(1,(int)Math.Ceiling(damage/(1+Bonus(a,"combat"))));}
 public static float TaxLocal(Kingdom k,float original){return Tax(k,original,"local");}public static float TaxTribute(Kingdom k,float original){return Tax(k,original,"tribute");}
 static float Tax(Kingdom k,float original,string key){int n;var d=Data(k);if(d==null)return original;d.get("godworld.tax."+key,out n,-1);return n<0?original:Math.Max(0,Math.Min(100,n))/100f;}
 public static object Selected(StatsWindow w){var m=w.GetType().GetMethod("getMetaObject",Flags,null,Type.EmptyTypes,null)??w.GetType().GetMethod("get_meta_object",Flags,null,Type.EmptyTypes,null);return m==null?null:m.Invoke(w,null);}
 public static void Show(StatsWindow w){try{var o=Selected(w);if(o==null||!Kinds.Contains(o.GetType().Name))return;var s=Get(o);NativeEconomyUI.ActionRow(w,"排名统计","第 "+revision+" 次 · 刷新 ▸",RequestRefresh);NativeEconomyUI.Extra(w,"组织ID",Data(o)==null?"—":Data(o).id.ToString());NativeEconomyUI.Extra(w,"组织加成作用",Effect(o.GetType().Name));NativeEconomyUI.Extra(w,"组织综合实力",s==null?"正在统计":s.score.ToString("0.0")+" · 同类第 "+s.rank+" 名");NativeEconomyUI.Extra(w,"实力构成",s==null?"人口 · 财富 · 原生能力 · 军力 · 发展":"人口 "+s.population+" · 财富 "+s.wealth.ToString("0")+" · 人才 "+s.talent.ToString("0")+" · 军力 "+s.military.ToString("0")+" · 发展 "+s.development.ToString("0"));NativeEconomyUI.Extra(w,"组织加成",(Strength(o)*100).ToString("0")+"% · "+(Mode(o)==0?"动态竞争":Mode(o)==1?"已关闭":"手动设置"));var anchor=NativeEconomyUI.ActionRow(w,"编辑组织","展开 ▸",null);NativeEconomyUI.BindAction(anchor,()=>NativeEconomyEditors.AttachOrganization(w,anchor.transform.parent));}catch(Exception e){Debug.LogWarning("GodWorld organization UI: "+e.Message);}}
 static void Demote(Actor actor){if(actor==null||actor.isKing())return;var m=actor.GetType().GetMethods(Flags).FirstOrDefault(x=>x.Name=="setProfession"&&x.GetParameters().Length==2);if(m!=null)m.Invoke(actor,new object[]{Enum.Parse(m.GetParameters()[0].ParameterType,"Unit"),true});}
 public static void RequestRefresh(){next=0;}
 public static object Find(int kind,long id){foreach(var o in Objects(kind)){var d=Data(o);if(d!=null&&d.id==id&&Alive(o))return o;}return null;}
 public static Actor FindActor(long id){var manager=Member(World.world,"units");var list=manager as IEnumerable;var method=manager==null?null:manager.GetType().GetMethod("getSimpleList",Flags,null,Type.EmptyTypes,null);if(method!=null)list=method.Invoke(manager,null) as IEnumerable;if(list!=null)foreach(var item in list){var a=item as Actor;if(a!=null&&a.isAlive()&&((ActorData)a.getData()).id==id)return a;}return null;}
 public static string Edit(object o,string action,long id,string text){if(o==null)throw new Exception("未选择组织");var d=Data(o);if(d==null)throw new Exception("组织没有可保存数据");var kind=o.GetType().Name;
  if(action=="name"){text=(text??"").Trim();if(text.Length==0||text.Length>64)throw new Exception("名称长度需为1至64字");var setter=o.GetType().GetMethod("setName",Flags,null,new[]{typeof(string),typeof(bool)},null);if(setter!=null)setter.Invoke(o,new object[]{text,true});else d.name=text;d.custom_name=true;return "名称已保存";}
  if(action=="trait+"||action=="trait-"){if(kind=="Family"||kind=="Alliance"||kind=="City")throw new Exception("此组织没有独立原生特质，编辑其成员或所属组织");text=(text??"").Trim();var traits=Invoke(o,"get_trait_library");var asset=Invoke(traits,"get",text);if(asset==null)throw new Exception("此组织没有该特质ID");if(action=="trait+"){var added=Invoke(o,"addTrait",text,true);if(added is bool&&!(bool)added)throw new Exception("原生适用性或互斥规则拒绝此特质");}else Invoke(o,"removeTrait",text);return "原生特质已修改";}
  if(action=="taxLocal"||action=="taxTribute"){if(kind!="Kingdom"||id< -1||id>100)throw new Exception("税率范围0至100，-1恢复原生");d.set(action=="taxLocal"?"godworld.tax.local":"godworld.tax.tribute",(int)id);return "税率已接入原生结算";}
  if(action=="cityKingdom"){if(kind!="City")throw new Exception("请选择城市");var k=Find(1,id);if(k==null)throw new Exception("未找到王国");Invoke(o,"joinAnotherKingdom",k,false,false);return "城市归属已修改";}
  if(action=="alliance+"||action=="alliance-"){if(kind!="Alliance")throw new Exception("请选择联盟");var k=Find(1,id);if(k==null)throw new Exception("未找到王国");if(action=="alliance+"){var old=AllianceOf(k as Kingdom);if(old!=null&&!System.Object.ReferenceEquals(old,o))throw new Exception("请先将王国移出原联盟，完成原联盟资金结算");var ok=Invoke(o,"join",k,true,true);if(ok is bool&&!(bool)ok)throw new Exception("原生规则拒绝加入");}else{if(!(bool)Invoke(o,"hasKingdom",k))throw new Exception("王国不属于此联盟");Invoke(o,"leave",k,true);}return "联盟成员已修改";}
  var actor=FindActor(id);if(actor==null)throw new Exception("未找到存活人物ID");if(action=="member"){var assetGetter=o.GetType().GetMethod("getActorAsset",Flags,null,Type.EmptyTypes,null);if(assetGetter!=null){var targetAsset=assetGetter.Invoke(o,null);var actorAsset=Member(actor,"asset");if(targetAsset!=null&&actorAsset!=null&&!System.Object.ReferenceEquals(targetAsset,actorAsset))throw new Exception("成员物种与组织不匹配");}string method=kind=="City"?"joinCity":kind=="Kingdom"?"joinKingdom":kind=="Family"?"setFamily":kind=="Clan"?"setClan":kind=="Culture"?"setCulture":kind=="Religion"?"setReligion":kind=="Language"?"joinLanguage":kind=="Subspecies"?"setSubspecies":null;if(method==null)throw new Exception("联盟成员请使用王国ID");Invoke(actor,method,o);return "成员已通过原生接口加入";}
  if(action=="leader"){bool belongs=Units(o).Cast<object>().Any(x=>System.Object.ReferenceEquals(x,actor));if(!belongs||actor.isBaby())throw new Exception("领袖必须是本组织成年成员");if(kind=="City"){if(actor.isKing())throw new Exception("国王不能兼任城市领导");var old=Member(o,"leader") as Actor;if(old==actor)return "该人物已经是领袖";if(old!=null){Invoke(o,"removeLeader");Demote(old);}Invoke(o,"setLeader",actor,true);}else if(kind=="Kingdom"){var old=Member(o,"king") as Actor;if(old==actor)return "该人物已经是国王";if(old!=null)Invoke(o,"removeKing");var home=actor.getCity();if(home!=null&&home.leader==actor)Invoke(home,"removeLeader");Invoke(o,"setKing",actor,false);}else if(kind=="Clan"){Invoke(o,"chiefLeft");Invoke(o,"setChief",actor);}else if(kind=="Family")Invoke(o,"setAlpha",actor,true);else throw new Exception("此类组织没有此原生领袖接口");return "领袖已修改";}
  throw new Exception("不支持的操作");
 }
}
